  return useQuery({
    queryKey: asOfKey(plansKey(sheet), asOf),
    queryFn: () => getJson<Plan[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/plans`, asOf)),
    staleTime: 0,
    gcTime: 0,
